CREATE DATABASE IF NOT EXISTS noble_erp CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE noble_erp;
CREATE TABLE IF NOT EXISTS roles(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(40) NOT NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS permissions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(100) NOT NULL UNIQUE,name VARCHAR(150) NOT NULL);
CREATE TABLE IF NOT EXISTS role_permissions(role_id BIGINT UNSIGNED NOT NULL,permission_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(role_id,permission_id),FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE,FOREIGN KEY(permission_id) REFERENCES permissions(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,role_id BIGINT UNSIGNED NOT NULL,username VARCHAR(120) NOT NULL UNIQUE,email VARCHAR(190) NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,active TINYINT(1) NOT NULL DEFAULT 1,last_login_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE IF NOT EXISTS departments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(30) NOT NULL UNIQUE,name VARCHAR(150) NOT NULL,status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS programs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,department_id BIGINT UNSIGNED NOT NULL,code VARCHAR(40) NOT NULL UNIQUE,name VARCHAR(150) NOT NULL,duration_years DECIMAL(3,1) NOT NULL DEFAULT 3,degree_type VARCHAR(80) NOT NULL,status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(department_id) REFERENCES departments(id));
CREATE TABLE IF NOT EXISTS semesters(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,program_id BIGINT UNSIGNED NOT NULL,number TINYINT UNSIGNED NOT NULL,academic_year VARCHAR(20) NOT NULL,start_date DATE NULL,end_date DATE NULL,UNIQUE(program_id,number,academic_year),FOREIGN KEY(program_id) REFERENCES programs(id));
CREATE TABLE IF NOT EXISTS divisions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,program_id BIGINT UNSIGNED NOT NULL,semester_id BIGINT UNSIGNED NOT NULL,name VARCHAR(30) NOT NULL,capacity INT UNSIGNED NOT NULL DEFAULT 60,UNIQUE(program_id,semester_id,name),FOREIGN KEY(program_id) REFERENCES programs(id),FOREIGN KEY(semester_id) REFERENCES semesters(id));
CREATE TABLE IF NOT EXISTS students(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL UNIQUE,student_id VARCHAR(60) NOT NULL UNIQUE,enrollment_no VARCHAR(80) NOT NULL UNIQUE,admission_no VARCHAR(80) NULL UNIQUE,first_name VARCHAR(80) NOT NULL,middle_name VARCHAR(80) NULL,last_name VARCHAR(80) NULL,gender VARCHAR(30) NULL,dob DATE NULL,mobile VARCHAR(25) NULL,email VARCHAR(190) NULL,address TEXT NULL,city VARCHAR(80) NULL,state VARCHAR(80) NULL,pincode VARCHAR(12) NULL,guardian_name VARCHAR(150) NULL,parent_mobile VARCHAR(25) NULL,emergency_contact VARCHAR(25) NULL,department_id BIGINT UNSIGNED NOT NULL,program_id BIGINT UNSIGNED NOT NULL,semester_id BIGINT UNSIGNED NULL,division_id BIGINT UNSIGNED NULL,roll_no VARCHAR(40) NULL,academic_year VARCHAR(20) NULL,admission_date DATE NULL,photo_path VARCHAR(255) NULL,status ENUM('active','inactive','graduated','blocked') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(department_id) REFERENCES departments(id),FOREIGN KEY(program_id) REFERENCES programs(id),FOREIGN KEY(semester_id) REFERENCES semesters(id) ON DELETE SET NULL,FOREIGN KEY(division_id) REFERENCES divisions(id) ON DELETE SET NULL,INDEX idx_students_academic(department_id,program_id,semester_id,division_id));
CREATE TABLE IF NOT EXISTS faculty(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL UNIQUE,faculty_id VARCHAR(60) NOT NULL UNIQUE,name VARCHAR(150) NOT NULL,email VARCHAR(190) NULL,mobile VARCHAR(25) NULL,department_id BIGINT UNSIGNED NOT NULL,designation VARCHAR(100) NULL,qualification VARCHAR(150) NULL,experience_years DECIMAL(5,2) NULL,joining_date DATE NULL,photo_path VARCHAR(255) NULL,status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(department_id) REFERENCES departments(id));
CREATE TABLE IF NOT EXISTS subjects(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,department_id BIGINT UNSIGNED NOT NULL,program_id BIGINT UNSIGNED NOT NULL,semester_id BIGINT UNSIGNED NOT NULL,code VARCHAR(50) NOT NULL UNIQUE,name VARCHAR(180) NOT NULL,credits DECIMAL(4,1) NOT NULL DEFAULT 0,type ENUM('theory','practical','both') NOT NULL DEFAULT 'theory',internal_marks DECIMAL(6,2) NOT NULL DEFAULT 0,external_marks DECIMAL(6,2) NOT NULL DEFAULT 0,status ENUM('active','inactive') NOT NULL DEFAULT 'active',FOREIGN KEY(department_id) REFERENCES departments(id),FOREIGN KEY(program_id) REFERENCES programs(id),FOREIGN KEY(semester_id) REFERENCES semesters(id));
CREATE TABLE IF NOT EXISTS faculty_subjects(faculty_id BIGINT UNSIGNED NOT NULL,subject_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(faculty_id,subject_id),FOREIGN KEY(faculty_id) REFERENCES faculty(id) ON DELETE CASCADE,FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS enrollments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_id BIGINT UNSIGNED NOT NULL,program_id BIGINT UNSIGNED NOT NULL,semester_id BIGINT UNSIGNED NOT NULL,division_id BIGINT UNSIGNED NULL,academic_year VARCHAR(20) NOT NULL,status ENUM('active','completed','cancelled') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(student_id,semester_id,academic_year),FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE,FOREIGN KEY(program_id) REFERENCES programs(id),FOREIGN KEY(semester_id) REFERENCES semesters(id),FOREIGN KEY(division_id) REFERENCES divisions(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS attendance(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,subject_id BIGINT UNSIGNED NOT NULL,faculty_id BIGINT UNSIGNED NOT NULL,division_id BIGINT UNSIGNED NOT NULL,attendance_date DATE NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(subject_id,division_id,attendance_date),FOREIGN KEY(subject_id) REFERENCES subjects(id),FOREIGN KEY(faculty_id) REFERENCES faculty(id),FOREIGN KEY(division_id) REFERENCES divisions(id));
CREATE TABLE IF NOT EXISTS attendance_records(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,attendance_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,status ENUM('present','absent','late','excused') NOT NULL,marked_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(attendance_id,student_id),FOREIGN KEY(attendance_id) REFERENCES attendance(id) ON DELETE CASCADE,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS audit_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,action VARCHAR(100) NOT NULL,module VARCHAR(100) NOT NULL,record_id BIGINT UNSIGNED NULL,ip_address VARCHAR(45) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL,INDEX idx_audit_created(created_at));
INSERT IGNORE INTO roles(name) VALUES('SUPER_ADMIN'),('ADMIN'),('HOD'),('FACULTY'),('STUDENT'),('PARENT');